/* Incidents and groups are generated by Jekyll from
   _projects/wwta/incidents/*.md and _projects/wwta/groups/*.md. */
let datasetPromise = null;

function loadDataset() {
  if (!datasetPromise) {
    const root = document.documentElement.dataset.baseurl || '';
    datasetPromise = fetch(`${root}/assets/data/wwta.json`).then((response) => {
      if (!response.ok) throw new Error('Failed to load the WWTA dataset');
      return response.json();
    });
  }
  return datasetPromise;
}

function formatDate(date) {
  return new Intl.DateTimeFormat('en', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  }).format(new Date(date));
}

function compareDates(a, b) {
  return new Date(a).getTime() - new Date(b).getTime();
}

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function cardMarkup(incident) {
  return `
    <article class="card">
      <div class="card-header">
        <div>
          <span class="badge">${escapeHtml(incident.group_name)}</span>
          <h3><a href="${escapeHtml(incident.url)}">${escapeHtml(incident.title)}</a></h3>
        </div>
        <time datetime="${escapeHtml(incident.date)}">${formatDate(incident.date)}</time>
      </div>
      <p>${escapeHtml(incident.summary)}</p>
      <div class="mini-meta">
        <span>${escapeHtml(incident.region)}</span>
        <span>•</span>
        <span>${escapeHtml(incident.target)}</span>
      </div>
    </article>
  `;
}
